-- rodar estes

-- produtos site magento

select *
  from Produto with (nolock)
 where ProdutoCodigo in('5970032')

declare @codigo varchar(15)

set @codigo='7440005'

-- elimina imagem

--begin tran
delete ProdutoImagem
 where ProdutoId in(select ProdutoId
                      from Produto with (nolock)
                     where ProdutoCodigo=@codigo
                   )

--rollback tran 
--commit tran

-- elimina categoria

--begin tran
delete ProdutoCategoria
 where ProdutoId in(select ProdutoId
                      from Produto with (nolock)
                     where ProdutoCodigo in(@codigo)
                   )

--rollback tran 
--commit tran

--begin tran
delete Produto
 where ProdutoCodigo in (@codigo)

--rollback tran
--commit tran


