-- elimina imagem

--begin tran
delete ProdutoImagem
 where ProdutoId in(select ProdutoId
                      from Produto with (nolock)
                     where ProdutoCodigo in (select ProdutoCodigo from #codigos)
                   )

--rollback tran 
--commit tran

-- elimina categoria

--begin tran
delete ProdutoCategoria
 where ProdutoId in(select ProdutoId
                      from Produto with (nolock)
                     where ProdutoCodigo in (select ProdutoCodigo from #codigos)
                   )

--rollback tran 
--commit tran

--begin tran
delete Produto
 where ProdutoCodigo in (select ProdutoCodigo from #codigos)